// The Statement Analyzer demo's seed as the statement pipeline's stand-in records: every run with its accounts,
// positions and edits, the destination accounts, the receiving custodian's roster and the fund restriction list,
// read from data/statement-runs.json (regenerated by scripts/demo-statements-snapshot.py) and placed relative to the
// seed's clock by the Statement Analyzer's own rules, so both demos show the same runs on the same day:
//   a run          business days before today (weekdays), at 9:00 ET plus minutes (demo_reset.business_day_before)
//   an edit        minutes after its run
//   a statement    a sample's printed date moved by whole weeks from the universe's as-of date (the replay's shift);
//                  an earlier quarter's or a generated household's, the month that ended before its run
// Ids are stable UUIDs from each record's place in the snapshot. Pure: no database.

import snapshot from "./data/statement-runs.json";
import { firmToday } from "./calendar";
import { demoUuid, type Universe } from "./universe";
import type {
  FundRestriction, PipelineAccount, PipelineDestination, PipelineHousehold, PipelinePosition, RosterAccount,
} from "../stand-ins/pipeline";

type Json = Record<string, unknown>;
interface SnapshotPosition extends Json {
  overridden_after?: number;
  transferring_after?: number;
  deleted_after?: number;
}
interface SnapshotAccount extends Json {
  statement: { printed: string } | { monthEndBeforeRun: number };
  custodian_intel?: number;
  deleted_after?: number;
  account_type_overridden_after?: number;
  assets: SnapshotPosition[];
}
interface SnapshotRun {
  key: string;
  source_folder_id: string;
  client_name: string;
  run_number: number;
  business_days_before: number;
  minutes_after_nine: number;
  superseded_by: string | null;
  total_value: number | null;
  docs_total: number;
  docs_extracted: number;
  doc_results: unknown;
  reviewed_by: string | null;
  reviewed_after: number | null;
  accounts: SnapshotAccount[];
}
interface Snapshot {
  custodian_intel: Json[];
  runs: SnapshotRun[];
  destinations: Array<Omit<PipelineDestination, "id" | "sources"> & { sources: Array<{ custodian: string | null; account_number: string | null }> }>;
  roster: RosterAccount[];
  fund_restrictions: FundRestriction[];
}

const SNAPSHOT = snapshot as unknown as Snapshot;

// Every field the pipeline's bulk read returns for an account and a position; the snapshot leaves empty ones out.
const ACCOUNT_FIELDS = [
  "custodian", "account_type", "account_type_raw", "account_type_other", "account_number", "investor_number",
  "account_registration", "account_holder", "cash_balance", "total_value", "cost_basis_status", "is_rollover",
  "rollover_note", "is_inherited", "inherited_note", "apex_restriction", "apex_special_handling", "validation_status",
  "validation_issues", "deleted_by", "account_type_overridden_by",
] as const;
const POSITION_FIELDS = [
  "symbol", "description", "quantity", "market_value", "cost_basis", "cost_basis_granularity", "lots", "asset_type",
  "classification_source", "transfer_eligible", "transfer_notes", "original_transfer_eligible", "notion_check",
  "override_status", "override_notes", "overridden_by", "transferring", "transferring_by", "deleted_by",
] as const;

const pickFields = (source: Json, fields: readonly string[]) =>
  Object.fromEntries(fields.map((f) => [f, source[f] ?? null]));

// --- New York days and times (the Statement Analyzer's clock) ---

const NEW_YORK = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/New_York", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit",
  second: "2-digit", hourCycle: "h23",
});

/** An instant from a New York calendar day and minutes after its midnight. */
export function newYorkInstant(day: string, minutes: number): Date {
  const guess = Date.UTC(Number(day.slice(0, 4)), Number(day.slice(5, 7)) - 1, Number(day.slice(8, 10)), 0, minutes);
  const p = Object.fromEntries(NEW_YORK.formatToParts(new Date(guess)).map((x) => [x.type, x.value]));
  const shown = Date.UTC(Number(p.year), Number(p.month) - 1, Number(p.day), Number(p.hour), Number(p.minute), Number(p.second));
  return new Date(guess - (shown - guess));
}

const utcDay = (day: string) => new Date(`${day}T00:00:00Z`);
const isoDay = (date: Date) => date.toISOString().slice(0, 10);

/** demo_reset.business_day_before: `days` weekdays before today in New York, at 9:00 ET plus `minutes`. */
export function businessDayBefore(now: Date, days: number, minutes: number): Date {
  const cursor = utcDay(firmToday(now));
  for (let counted = 0; counted < days; ) {
    cursor.setUTCDate(cursor.getUTCDate() - 1);
    if (cursor.getUTCDay() !== 0 && cursor.getUTCDay() !== 6) counted++;
  }
  return newYorkInstant(isoDay(cursor), 9 * 60 + minutes);
}

/** stand_ins.replay_shift_days: whole weeks from the universe's as-of date to today, so weekdays stay weekdays. */
export function replayShiftDays(universe: Universe, now: Date): number {
  const days = Math.round((utcDay(firmToday(now)).getTime() - utcDay(universe.meta.asOf).getTime()) / 86_400_000);
  return Math.max(0, days - (days % 7));
}

const usDate = (date: Date) =>
  `${String(date.getUTCMonth() + 1).padStart(2, "0")}/${String(date.getUTCDate()).padStart(2, "0")}/${date.getUTCFullYear()}`;

function statementDate(rule: SnapshotAccount["statement"], processedAt: Date, shift: number): string {
  if ("printed" in rule) {
    const [month, day, year] = rule.printed.split("/").map(Number);
    return usDate(new Date(Date.UTC(year, month - 1, day + shift)));
  }
  const runDay = utcDay(firmToday(processedAt));
  runDay.setUTCDate(runDay.getUTCDate() - rule.monthEndBeforeRun);
  return usDate(new Date(Date.UTC(runDay.getUTCFullYear(), runDay.getUTCMonth(), 0)));
}

/** The universe household a Statement Analyzer client folder belongs to: generated households by id, the nine sample
 *  households by name. */
const SAMPLE_HOUSEHOLD: Record<string, string> = { chen: "chen-ashby", delgado: "delgado-trust" };
export function folderHousehold(folder: string): string | null {
  if (folder.startsWith("universe-")) return folder.slice("universe-".length);
  if (folder.startsWith("sample-")) {
    const key = folder.slice("sample-".length);
    return SAMPLE_HOUSEHOLD[key] ?? key;
  }
  return null;
}

export interface StatementRunsPlan {
  households: PipelineHousehold[];
  destinations: PipelineDestination[];
  roster: RosterAccount[];
  fundRestrictions: FundRestriction[];
}

export const runId = (key: string) => demoUuid(`pipeline:run:${key}`);

/** Every stand-in record the statement pipeline starts the day with, relative to `now`, oldest run first. */
export function planStatementRuns(universe: Universe, now: Date): StatementRunsPlan {
  const shift = replayShiftDays(universe, now);
  const iso = (d: Date | null) => (d ? d.toISOString() : null);
  const households = SNAPSHOT.runs.map((run): PipelineHousehold => {
    const id = runId(run.key);
    const processedAt = businessDayBefore(now, run.business_days_before, run.minutes_after_nine);
    const after = (minutes: number | null | undefined) =>
      minutes == null ? null : new Date(processedAt.getTime() + minutes * 60_000);
    const edits: Date[] = [];
    const stamp = (minutes: number | null | undefined) => {
      const at = after(minutes);
      if (at) edits.push(at);
      return iso(at);
    };
    const accounts = run.accounts.map((a, ai) => {
      const accountId = demoUuid(`pipeline:account:${run.key}:${ai}`);
      const account: Json = {
        id: accountId,
        household_id: id,
        ...pickFields(a, ACCOUNT_FIELDS),
        statement_date: statementDate(a.statement, processedAt, shift),
        statement_age_days: null,
        is_stale: false,
        custodian_intel: a.custodian_intel == null ? null : SNAPSHOT.custodian_intel[a.custodian_intel],
        deleted_at: stamp(a.deleted_after),
        account_type_overridden_at: stamp(a.account_type_overridden_after),
        created_at: iso(processedAt),
        assets: a.assets.map((p, pi) => {
          const position: Json = {
            id: demoUuid(`pipeline:position:${run.key}:${ai}:${pi}`),
            account_id: accountId,
            ...pickFields(p, POSITION_FIELDS),
            overridden_at: stamp(p.overridden_after),
            transferring_at: stamp(p.transferring_after),
            deleted_at: stamp(p.deleted_after),
            created_at: iso(processedAt),
          };
          return position as unknown as PipelinePosition;
        }),
      };
      return account as unknown as PipelineAccount;
    });
    const reviewedAt = stamp(run.reviewed_after);
    const updatedAt = new Date(Math.max(processedAt.getTime(), ...edits.map((d) => d.getTime())));
    return {
      id,
      client_name: run.client_name,
      run_number: run.run_number,
      processed_at: iso(processedAt)!,
      superseded_by: run.superseded_by ? runId(run.superseded_by) : null,
      source_folder_id: run.source_folder_id,
      total_value: run.total_value,
      docs_total: run.docs_total,
      docs_extracted: run.docs_extracted,
      doc_results: run.doc_results,
      reviewed_at: reviewedAt,
      reviewed_by: run.reviewed_by,
      created_at: iso(processedAt),
      updated_at: iso(updatedAt),
      accounts,
    };
  });

  const destinations = SNAPSHOT.destinations.map((d, i): PipelineDestination => {
    const id = demoUuid(`pipeline:destination:${d.source_folder_id}:${i}`);
    return {
      id,
      source_folder_id: d.source_folder_id,
      owner: d.owner,
      target_account_type: d.target_account_type,
      existing_apex_number: d.existing_apex_number,
      needs_to_be_opened: d.needs_to_be_opened,
      sources: d.sources.map((s, k) => ({ link_id: demoUuid(`pipeline:source-link:${id}:${k}`), ...s })),
    };
  });

  return { households, destinations, roster: SNAPSHOT.roster, fundRestrictions: SNAPSHOT.fund_restrictions };
}
